import { test, expect, totp, secret, enterOtp } from '../../src/fixtures.ts';

test('An auditor cannot access the new payment screen', async ({ page }) => {
  await test.step('Open the app', async () => {
    await page.goto('/');
  });

  await test.step('Sign in as auditor', async () => {
    await page.getByLabel('Username', { exact: true }).fill(secret('auditor_user'));
    await page.getByLabel('Password', { exact: true }).fill(secret('auditor_pass'));
    await page.getByRole('button', { name: 'Sign in', exact: true }).click();
  });

  await test.step('Pass MFA', async () => {
    await enterOtp(page.getByRole('textbox'), totp(secret('auditor_totp')));
    await page.getByRole('button', { name: 'Verify', exact: true }).click();
  });

  await test.step('Attempt new payment', async () => {
    await page.goto('/payments/new');
    await page.getByRole('alert').waitFor({ state: 'visible' });
    await expect(page.getByRole('alert')).toContainText('keine Berechtigung');
  });
});
